arguments.command:
python3 - <<'EOF'
import json, glob

total = 0
for path in sorted(glob.glob('data/*.jsonl')):
    for line in open(path):
        rec = json.loads(line)
        if rec.get('kind') != 'span':
            continue
        el = rec.get('body', {}).get('span', {}).get('elapsed')
        if el is None:
            continue
        v, u = el['value'], el['unit']
        if u == 'us':
            total += v // 1000
        elif u == 'ms':
            total += v
        elif u == 's':
            total += v * 1000
        else:
            raise ValueError(u)
print(total)
EOF
